const items = $input.all();

const issues = items
  .filter(item => !item.json.pull_request)
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    url: item.json.html_url,
    closed_at: item.json.closed_at
  }));

return [{
  json: {
    issues
  }
}];

const items = $input.all();

const start = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

const pull_requests = items
  .filter(item => {
    const mergedAt = item.json.merged_at;
    return mergedAt && new Date(mergedAt) >= start;
  })
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    url: item.json.html_url,
    merged_at: item.json.merged_at
  }));

return [{
  json: {
    pull_requests
  }
}];

const items = $input.all();

const commits = items
  .filter(item => item.json.sha)
  .map(item => ({
    sha: item.json.sha,
    message: item.json.commit?.message || '',
    author: item.json.commit?.author?.name || '',
    date: item.json.commit?.author?.date || '',
    url: item.json.html_url || ''
  }));

return [{
  json: {
    commits
  }
}];

const commits = $('Format Commits').first()?.json.commits ?? [];
const issues = $('Format Closed Issues').first()?.json.issues ?? [];
const pull_requests = $('Format Merged PRs').first()?.json.pull_requests ?? [];

const config = $('Config').first()?.json ?? {};

const period_end = new Date();
const period_start = new Date(period_end.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    repository: `${config.github_owner}/${config.github_repo}`,
    language: config.language || 'en',

    period_start: period_start.toISOString(),
    period_end: period_end.toISOString(),
    period_days: 7,

    commit_count: commits.length,
    closed_issue_count: issues.length,
    merged_pr_count: pull_requests.length,

    commits,
    issues,
    pull_requests
  }
}];

const text = $('Claude Weekly Summary').first().json.content[0].text;

const maxLength = 1900;
const chunks = [];

let remaining = text;

while (remaining.length > maxLength) {
  let splitAt = remaining.lastIndexOf('\n', maxLength);

  if (splitAt <= 0) {
    splitAt = maxLength;
  }

  chunks.push(remaining.slice(0, splitAt).trim());
  remaining = remaining.slice(splitAt).trim();
}

if (remaining.length > 0) {
  chunks.push(remaining);
}

return chunks.map((chunk, index) => ({
  json: {
    content: chunk,
    part: index + 1,
    total: chunks.length
  }
}));
